import os
import requests

def compare_metric_series(payload, config=None):
    config = config or {}
    api_key = config.get("dd_api_key") or os.environ.get("DD_API_KEY")
    app_key = config.get("dd_app_key") or os.environ.get("DD_APP_KEY")
    headers = {
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key,
        "Content-Type": "application/json"
    }
    result = requests.post("https://api.datadoghq.com/api/v2/query/scalar", headers=headers, json=payload, timeout=30).json()
    return result
